import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-card-thumbnail';

  const pos = config.scenePosition?.position ?? { x: -2.5, y: -0.2, z: 0 };
  const rot = config.scenePosition?.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.scenePosition?.scale ?? { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accent = new THREE.Color('#ff2a38');
  const surface = new THREE.Color('#0b0b10');

  // Caption strip (fallback plane) built immediately so card has presence before GLB loads
  const captionGeo = new THREE.PlaneGeometry(1.6, 0.36);
  const captionMat = new THREE.MeshStandardMaterial({
    color: ink,
    metalness: 0.4,
    roughness: 0.6,
  });
  const captionStrip = new THREE.Mesh(captionGeo, captionMat);
  captionStrip.position.set(0, -0.9, 0.01);
  group.add(captionStrip);

  // Accent edge (focus indicator), hidden by default
  const edgeGeo = new THREE.PlaneGeometry(1.72, 1.4);
  const edgeMat = new THREE.MeshBasicMaterial({
    color: accent,
    transparent: true,
    opacity: 0.0,
  });
  const accentEdge = new THREE.Mesh(edgeGeo, edgeMat);
  accentEdge.position.set(0, -0.35, -0.02);
  group.add(accentEdge);

  // Backing card surface behind the mesh
  const backGeo = new THREE.PlaneGeometry(1.6, 1.2);
  const backMat = new THREE.MeshStandardMaterial({
    color: surface,
    metalness: 0.3,
    roughness: 0.7,
  });
  const backing = new THREE.Mesh(backGeo, backMat);
  backing.position.set(0, -0.35, -0.015);
  group.add(backing);

  let meshRoot = null;
  const baseY = 0;

  try {
    const glb = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
    if (glb && glb.scene) {
      meshRoot = glb.scene;
      meshRoot.position.set(0, 0.15, 0);
      meshRoot.scale.setScalar(0.9);
      group.add(meshRoot);
    }
  } catch (e) {
    // mesh unavailable, card still functions with fallback visuals
  }

  const timelines = [];
  let hovered = false;
  let pressed = false;

  function killTimelines() {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  }

  function onPointerOver() {
    if (hovered) return;
    hovered = true;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: pos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    tl.to(accentEdge.material, {
      opacity: 0.35,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(tl);
  }

  function onPointerOut() {
    hovered = false;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: pos.y,
      duration: 0.7,
      ease: 'power3.out',
    });
    tl.to(accentEdge.material, {
      opacity: 0.0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(tl);
  }

  function onPointerDown() {
    pressed = true;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: scl.x * 0.97,
      y: scl.y * 0.97,
      z: scl.z * 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
    timelines.push(tl);
  }

  function onPointerUp() {
    pressed = false;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: scl.x,
      y: scl.y,
      z: scl.z,
      duration: 0.12,
      ease: 'back.out',
    });
    timelines.push(tl);
  }

  function onClick() {
    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { nodeId: 'home-card-thumbnail' });
    }
  }

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
  };

  group.userData.cleanup = function cleanup() {
    killTimelines();
    captionGeo.dispose();
    captionMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    backGeo.dispose();
    backMat.dispose();
    if (meshRoot) {
      meshRoot.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material?.dispose();
          }
        }
      });
    }
  };

  return group;
}
